  "firstMeeting.maki": "Erst mal die Diagnose, miau. Ich seh vielleicht so aus, bin aber Arzt, miau!",
  "firstMeeting.keris": "Senpai, suchen Sie ein Buch? Ich zeige Ihnen, wo es steht.",
  "firstMeeting.delopi": "Tadaa! Hier ist dein Schlüssel, Forscher.",
  "firstMeeting.nodonia": "Sag Bescheid, wenn es wehtut, Kleines. Ich fange den Schlag für dich ab.",
  "firstMeeting.ella": "Ich halte die Stellung. Überlass mir die Nachhut.",
  "firstMeeting.mette": "Die Bühne nur für dich beginnt jetzt.",
  "firstMeeting.deina": "Ich bin Dei! Diese Wand ist ja noch ganz leer! Darf ich hier was malen?",
  "firstMeeting.maddy": "Ich bin Maddy, Forscher. Es ist etwas heiß hier. Darf ich die Kühlung stärker stellen?",
  "firstMeeting.terisa": "Wenn irgendwo etwas gerissen ist, sagen Sie Bescheid… Ich nähe es Ihnen.",
  "firstMeeting.parua": "Weit… so weit! Ich kann alles sehen.",
  "firstMeeting.shute": "Doch nicht das! Hör auf meine Ansagen, ich carry dich.",
  "firstMeeting.morphe": "…Leitstelle? Schön, dass du da bist. Moment… Ich zeige dir den Bildschirm.",
  "firstMeeting.dian": "Ich beschütze dich, Captain! …Ah, Kuro! Shiro! Kommt her!",
